import{_ as o,c as e,o as a,a3 as n}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Usage Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1787284674000}'),r={name:"guide/usage.md"};function i(l,t,s,d,u,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="usage-guide" tabindex="-1">Usage Guide <a class="header-anchor" href="#usage-guide" aria-label="Permalink to &quot;Usage Guide&quot;">​</a></h1><h2 id="clipboard-history" tabindex="-1">Clipboard History <a class="header-anchor" href="#clipboard-history" aria-label="Permalink to &quot;Clipboard History&quot;">​</a></h2><p>ClipboxAI runs from your <strong>menu bar</strong>. Every time you copy something, it&#39;s added to your history.</p><ul><li>Click the menu bar icon to open the history panel.</li><li>Hover an item and press the action shortcut, or click to copy it back to the pasteboard.</li><li>Use the search field to find an item by text.</li></ul><h2 id="the-ai-tool-window" tabindex="-1">The AI Tool Window <a class="header-anchor" href="#the-ai-tool-window" aria-label="Permalink to &quot;The AI Tool Window&quot;">​</a></h2><p>The <strong>AI Tool</strong> window is where actions run. It uses a split layout:</p><ul><li><strong>Left</strong> — a list of tools, grouped into: <ul><li><strong>Built-in AI</strong> — summary, translate, and other AI actions.</li><li><strong>Built-in Local</strong> — offline tools (extract links, count stats, collapse blank lines).</li><li><strong>Installed</strong> — actions you added from the Marketplace. You can drag to <strong>reorder</strong> them.</li></ul></li><li><strong>Right</strong> — two panes: the <strong>original</strong> clip on one side and the <strong>result</strong> on the other.</li></ul><p>AI tools show a &quot;cloud&quot; badge; local tools show a &quot;device&quot; badge, so you always know whether an action uses the network.</p><h2 id="running-an-action" tabindex="-1">Running an Action <a class="header-anchor" href="#running-an-action" aria-label="Permalink to &quot;Running an Action&quot;">​</a></h2><ol><li>Select a tool from the left list (or accept a smart suggestion).</li><li>The current clip appears in the <strong>original</strong> pane.</li><li>The result is produced in the <strong>result</strong> pane.</li></ol><h3 id="auto-run" tabindex="-1">Auto-run <a class="header-anchor" href="#auto-run" aria-label="Permalink to &quot;Auto-run&quot;">​</a></h3><p>Turn on <strong>Auto-run on output</strong> in the window footer. When enabled, the selected tool runs automatically the moment you copy something — no manual click needed. Local tools never overwrite your pasteboard, so auto-run is safe.</p><h2 id="built-in-local-tools" tabindex="-1">Built-in Local Tools <a class="header-anchor" href="#built-in-local-tools" aria-label="Permalink to &quot;Built-in Local Tools&quot;">​</a></h2><p>These run fully offline on your Mac:</p><ul><li><strong>Extract Links</strong> — returns every URL found in the text.</li><li><strong>Count Stats</strong> — word / character / line / sentence counts.</li><li><strong>Collapse Blank Lines</strong> — removes empty lines from pasted text.</li></ul><h2 id="cloud-ai-setup" tabindex="-1">Cloud AI Setup <a class="header-anchor" href="#cloud-ai-setup" aria-label="Permalink to &quot;Cloud AI Setup&quot;">​</a></h2><p>To use AI actions, connect a provider in <strong>Settings → AI</strong>:</p><ol><li>Choose a provider — <strong>DeepSeek</strong>, <strong>MiniMax</strong>, <strong>Zhipu GLM</strong>, <strong>Kimi (Moonshot)</strong>, <strong>Mistral</strong>, <strong>Ollama</strong> (local), or another OpenAI-compatible service.</li><li>Paste your <strong>API key</strong>. It is stored in the <strong>Keychain</strong>, never written to disk in plain text.</li><li>Pick a model.</li><li>Cloud AI is off by default. When enabled, your clip is sent only to the provider you configured.</li></ol><p>If no key is set, the config banner reminds you inside the AI Tool window.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong> from the AI Tool window (or the site&#39;s <a href="/marketplace/">Marketplace</a> page).</li><li>Click <strong>Install</strong> on an action. This opens the app via the deep link <code>clipboxai://install?action=&lt;id&gt;</code> and adds the action to your <strong>Installed</strong> list.</li></ol><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>Open clipboard history</td></tr><tr><td><code>Cmd+,</code></td><td>Open Settings</td></tr><tr><td><code>Cmd+W</code></td><td>Close window</td></tr><tr><td><code>Cmd+Q</code></td><td>Quit application</td></tr></tbody></table><blockquote><p>Exact shortcuts may vary by build; check <strong>Settings → Shortcuts</strong> in the app.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open <strong>ClipboxAI → Settings</strong> (or <code>Cmd+,</code>):</p><ul><li><strong>General</strong>: Language, launch at login, appearance theme.</li><li><strong>AI</strong>: Cloud provider, model, and API key (Keychain).</li><li><strong>Actions</strong>: Auto-run toggle, excluded apps, and tool order.</li><li><strong>Privacy</strong>: Cloud AI opt-in, excluded apps, and history controls.</li><li><strong>Marketplace</strong>: Browse and manage installed actions.</li></ul>',27)])])}const p=o(r,[["render",i]]);export{g as __pageData,p as default};
